layer.css:
@import url("https://fonts.googleapis.com/css2?family=Fira+Sans+Condensed:wght@300;400;500&family=Bitter:ital,wght@0,400;0,600;0,700;1,400&display=swap");
[data-ryt="footer"] { color: var(--ryt-text); font-style: italic; letter-spacing: normal; text-transform: none }
[data-ryt="pitch"] { color: rgb(58, 47, 47); border-left: 3px solid var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 17.6px; font-weight: 400; font-style: italic; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(58, 47, 47); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 17.6px; transition: all; border-top: none; border-right: none; border-bottom: none }
article[data-ryt="rec-card"] { background-color: var(--ryt-surface); border-top: 1px solid var(--ryt-border); border-right: 1px solid var(--ryt-border); border-bottom: 1px solid var(--ryt-border); border-left: 1px solid var(--ryt-border); border-radius: 12px; box-shadow: rgba(40, 25, 20, 0.08) 0px 1px 2px 0px, rgba(40, 25, 20, 0.08) 0px 8px 24px 0px; transition: all }
[data-ryt="hero"] h1 { color: var(--ryt-text); font-family: var(--ryt-font-heading); font-size: 41.6px; font-weight: 600; font-style: normal; line-height: 1.25; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="cover"] { border-radius: 0px }
[data-ryt="brand"] { color: var(--ryt-text); border-radius: 0px; font-family: "fira sans condensed", sans-serif; font-size: 24px; font-weight: 400; font-style: normal; line-height: 1.15; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a { color: rgb(91, 83, 80); border-radius: 0px; font-family: "fira sans condensed", sans-serif; font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.15; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(91, 83, 80); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 16px; padding-right: 16px; padding-bottom: 16px; padding-left: 16px; transition: all }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: 1px; text-underline-offset: 3px; transition: all }
[data-ryt="review"] { color: var(--ryt-text); font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.65; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-muted); font-family: var(--ryt-font-heading); font-size: 12.8px; font-weight: 400; font-style: normal; line-height: 1.65; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 600; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 32px; font-weight: 600; font-style: normal; line-height: 1.25; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a:hover { background-color: rgb(238, 238, 238); color: light-dark(#1f1a1a, #e9e2e2) }
[data-ryt="brand"]:hover { color: light-dark(#1f1a1a, #e9e2e2) }
